import {sources,lessons,assignments,metricDefinitions} from './course.mjs';
import {aggregate,groupRows,filteredRows,divide} from './analytics.mjs';
import {esc,num,usd,pct,bars,scatter,metricCards,metricsTable} from './charts.mjs';
import {overview,datasetIntro,caseStory,questionSource,sourceMapping,fieldDictionary} from './app.mjs';
import {investigationViews} from './investigation-views.mjs';
import {workedSolution,inspectButton} from './solutions.mjs';
import {dataExplorer} from './data-explorer.mjs';
export function views(state,localAvailable){
const extra=investigationViews(state);
const head=(label,title,desc,extra='')=>`<div class="page-head"><div><div class="eyebrow">${label}</div><h1>${title}</h1><p>${desc}</p></div>${extra}</div>`;
const source=()=>state.data?`<div class="source-note"><span class="pill">${state.data.meta.sourceKind==='public-course-mirror'?'公开课程镜像':'本地导入文件'}</span><span>${esc(state.data.meta.filename)} · ${num(state.data.rows.length)} 条记录</span><a href="#data">查看来源与检查 →</a></div>`:'';
const empty=()=>`<div class="empty"><div class="badge-icon">▥</div><strong>先导入案例表格，再开始计算</strong><p>图表、指标与数值校验从 KEL321 文件计算，不预填示例经营数据。</p><a class="button primary" href="#data">准备案例数据 →</a></div>`;
const note=extra.note;
const pager=(page,count,size,action)=>`<div class="pagination"><span>${num(count)} 条 · 第 ${page+1} / ${Math.max(1,Math.ceil(count/size))} 页</span><div><button class="button compact" data-action="${action}" data-delta="-1" ${page===0?'disabled':''}>上一页</button> <button class="button compact" data-action="${action}" data-delta="1" ${(page+1)*size>=count?'disabled':''}>下一页</button></div></div>`;
const pairs=rows=>`<div class="result-list">${rows.map(([a,b])=>`<div><span>${a}</span><strong>${b}</strong></div>`).join('')}</div>`;
function task(id){const a=assignments[id];return `<div class="grid-main"><section class="panel question-panel"><div class="eyebrow">问题 / 业务背景与任务</div><h2>${a.question}</h2><p>${a.context}</p><ol class="task-list">${a.tasks.map((t,i)=>`<li><span class="task-index">${i+1}</span><div><h3>${t[0]}</h3><p>${t[1]}</p></div></li>`).join('')}</ol></section><aside class="side-stack"><section class="panel aside-card"><h3>本题交付物</h3><p>${a.deliverable}</p><button class="button primary" data-action="tab" data-tab="analysis">交互探索当前数据 →</button><button class="button quiet" data-action="tab" data-tab="reference">记录自己的分析</button></section><section class="panel aside-card"><h3>本题依据</h3><p>${a.origin}</p><p class="small">对应实际案例讨论主题 ${a.originNumber}。以下为本课可复算参考答案，不是官方标准答案。</p><details><summary>查看来源与字段</summary>${questionSource(a)}<div class="tags">${a.fields.map(f=>`<span class="tag">${f}</span>`).join('')}</div></details></section></aside></div>${workedSolution(id,state.data)}`}

function q1(){const t=aggregate(state.data.rows),a=state.data.audit;return extra.audit()+metricCards(t)+`<section class="panel"><h2>投放路径与计数</h2><div class="funnel">${[['曝光',num(t.impressions),'Impressions'],['点击',num(t.clicks),'CTR '+pct(t.ctr)],['预订',num(t.bookings),'预订 / 点击 '+pct(t.cvr)],['销售收入',usd(t.revenue),'每次预订 '+usd(t.revenuePerBooking,2)]].map(([l,v,n])=>`<div><span>${l}</span><strong>${v}</strong><small>${n}</small></div>`).join('')}</div><p class="chart-caption">框宽不表示比例。不同事件计数不等于独立用户漏斗。</p></section><div class="two-columns"><section class="panel"><h2>检查指标的分母</h2>${pairs([['加权 CPC',usd(t.cpc,2)],['每次预订成本 CPA',usd(t.cpa,2)],['预订 / 点击 CVR',pct(t.cvr)],['销售收入 − 广告花费',usd(t.balance,2)]])}<div class="notice info"><p>广告费后余额尚未扣除履约等成本，不称为利润。</p></div></section><section class="panel"><h2>先检查，再判断</h2>${pairs([['预订量高于点击',a.bookingsAboveClicks+' 条'],['零预订',num(a.zeroBookings)+' 条'],['零点击',a.zeroClicks+' 条']])}<p class="small">异常记录保留在汇总中，应回到源头核对口径。</p><label for="cpa-check" class="field-label">自行计算整体 CPA（USD）</label><div class="flex"><input id="cpa-check" type="number" min="0" step="0.01" placeholder="输入你的计算值"><button class="button" data-action="check-cpa">核对</button></div><p id="cpa-feedback" role="status" class="small"></p></section></div>${note('q1')}`}
function q2(){const groups=groupRows(state.data.rows,'publisher'),t=aggregate(state.data.rows);return `<section class="panel"><div class="section-head no-margin"><h2>渠道的成本与转化表现</h2><button class="button compact" data-action="export-summary">导出渠道汇总 ↓</button></div>${scatter(groups,t)}</section><section class="panel"><h2>把规模与效率一起看</h2>${metricsTable(groups)}<p class="chart-caption">DoubleClick 全量汇总 · 保留渠道原始名称 · Kayak 独立分析</p></section><div class="two-columns"><section class="panel"><h2>预算花在哪里</h2>${bars(groups,{title:'广告花费'})}</section><section class="panel"><h2>读图后，再决定动作</h2><ul class="reading-list"><li>低 CPC、高 CVR：验证是否还有有效流量可获取。</li><li>高 CPC、高 CVR：结合 CPA 和每次预订收入判断成本。</li><li>低 CPC、低 CVR：检查关键词意图、广告与落地页的匹配。</li><li>高 CPC、低 CVR：继续下钻，考虑收缩或调整。</li></ul><p class="small">这些是诊断线索，优化的实际效果仍需验证。</p></section></div>${note('q2')}`}
function q3(){const data=state.data.rows,pubs=groupRows(data,'publisher'),scope=filteredRows(data,{publisher:state.publisher});const campaigns=groupRows(scope.map(r=>({...r,scopeCampaign:state.publisher?r.campaign:r.publisher+' / '+r.campaign})),'scopeCampaign');if(state.campaign&&!scope.some(r=>r.campaign===state.campaign))state.campaign='';const strategyScope=filteredRows(scope,{campaign:state.campaign});const detail=filteredRows(data,{publisher:state.publisher,campaign:state.campaign,query:state.query,minClicks:state.minClicks}).sort((a,b)=>b.cost-a.cost),size=12;state.page=Math.min(state.page,Math.max(0,Math.ceil(detail.length/size)-1));return `<section class="panel"><div class="filters"><label>渠道<select id="publisher-filter"><option value="">全部渠道（保留渠道 + 活动）</option>${pubs.map(p=>`<option ${state.publisher===p.name?'selected':''} value="${esc(p.name)}">${esc(p.name)}</option>`).join('')}</select></label><label>活动<select id="campaign-filter"><option value="">全部活动</option>${groupRows(scope,'campaign').map(c=>`<option ${state.campaign===c.name?'selected':''} value="${esc(c.name)}">${esc(c.name)}</option>`).join('')}</select></label><label>关键词包含<input type="search" id="keyword-query" value="${esc(state.query)}" placeholder="例如 air france"></label><label>关键词最少点击<input type="number" id="min-clicks" min="0" step="1" value="${state.minClicks}"></label><button class="button" data-action="apply-filters">应用筛选</button></div><p class="small no-margin">活动和关键词筛选影响明细；策略比较采用当前活动范围，活动总表保留当前渠道全量。点击门槛由分析者自定，默认 0，不是案例给定规则。</p></section><div class="two-columns"><section class="panel"><h2>哪些活动占用了主要预算</h2>${bars(campaigns,{title:'活动花费',limit:8})}</section><section class="panel"><h2>先圈定行动候选</h2>${pairs([['当前渠道',state.publisher?esc(state.publisher):'全部渠道'],['活动组合',num(campaigns.length)],['符合关键词筛选',num(detail.length)+' 条'],['其中零预订的花费',usd(aggregate(detail.filter(r=>r.bookings===0)).cost,2)]])}<p class="small">零预订只表示当前观察窗口没有记录到预订，不能直接证明未来没有价值。</p></section></div><section class="panel"><h2>活动经营对比</h2>${metricsTable(campaigns,{caption:'当前渠道范围内的全部渠道 / 活动组合，按花费排序',showPublisher:true})}</section><section class="panel"><h2>匹配方式与出价策略</h2>${metricsTable(groupRows(strategyScope.map(r=>({...r,strategy:(r.matchType||'未填写匹配方式')+' / '+(r.bidStrategy||'未填写出价策略')})),'strategy'),{caption:'当前渠道 / 活动内的策略组合；历史关联不证明策略效果',showPublisher:true})}<p class="small">工作簿没有广告文案或落地页内容。调整文案属于需要补充材料后验证的建议。</p></section><section class="panel"><div class="section-head no-margin"><h2>关键词行动清单</h2><button class="button compact" data-action="export-keywords">导出筛选结果 ↓</button></div><div class="table-scroll"><table><caption>关键词明细，按花费降序</caption><thead><tr><th>源行</th><th>渠道 / 活动 / 关键词</th><th>匹配 / 出价策略</th><th>点击</th><th>花费</th><th>预订</th><th>ROAS</th></tr></thead><tbody>${detail.slice(state.page*size,(state.page+1)*size).map(r=>`<tr><td>${inspectButton(r,'原行')}</td><th>${esc(r.keyword)}<small>${esc(r.publisher)} / ${esc(r.campaign)}</small></th><td>${esc(r.matchType)}<small>${esc(r.bidStrategy)}</small></td><td>${num(r.clicks)}</td><td>${usd(r.cost,2)}</td><td>${num(r.bookings)}</td><td>${num(divide(r.revenue,r.cost),2)}×</td></tr>`).join('')||'<tr><td colspan="7">没有符合条件的关键词，请调整筛选。</td></tr>'}</tbody></table></div>${pager(state.page,detail.length,size,'keywords-page')}</section>${note('q3')}`}
function q4(){
  const d=state.data, groups=groupRows(d.rows,'publisher'), k=d.kayak?aggregate([d.kayak]):null;
  return `<section class="panel"><div class="eyebrow">未来渠道选择 / KAYAK</div><h2>先把新增渠道的证据单独看清</h2><p>本题使用工作簿的 Kayak 汇总。下表不合并两个范围的总量，不生成预算或未来收益数字。</p>${k?`<p><strong>Kayak 期间：</strong>${esc(d.meta.kayakPeriod)}。<strong>DoubleClick：</strong>${esc(d.meta.period)}</p>${metricCards(k)}${metricsTable([{name:'Kayak · 独立期间',...k}],{caption:'Kayak 独立核算，费用与收入均为 USD'})}<div class="result-list"><div><span>每次预订收入</span><strong>${usd(k.revenuePerBooking,2)}</strong></div><div><span>收入减广告费（非利润）</span><strong>${usd(k.balance,2)}</strong></div><div><span>CTR</span><strong>${pct(k.ctr)}</strong></div></div><p class="small">Kayak 缺少曝光数据时 CTR 不可计算。不要以文件创建日期推定主表投放期间。</p>`:'<div class="notice"><p>当前导入文件没有可识别的 Kayak 工作表。本题保留题目，不能补造 Kayak 结果。请导入完整工作簿。</p></div><a class="button" href="#data">载入完整 Excel →</a>'}</section>${k?`<div class="notice"><p><strong>以下仅为不同范围的历史描述性参照。</strong>主表没有日期，无法确认同期；渠道结构、样本和统计期间不同。不能据此证明最优分配或投放因果增量。</p></div><div class="two-columns"><section class="panel"><h2>广告销售回报 · ROAS</h2>${bars([...groups,{name:'Kayak（独立单周）',...k}],{key:'roas',title:'ROAS',format:v=>num(v,2)+'×'})}</section><section class="panel"><h2>每次预订成本 · CPA</h2>${bars([...groups,{name:'Kayak（独立单周）',...k}],{key:'cpa',title:'CPA',format:v=>usd(v,2)})}</section></div>`:''}<section class="panel"><h2>形成未来 SEM 建议</h2><div class="flow"><div class="flow-step"><strong>经营目标</strong><span>引用第一题 KPI</span></div><div class="flow-step"><strong>现有渠道</strong><span>引用第二题策略</span></div><div class="flow-step"><strong>投放行动</strong><span>引用第三题源行</span></div><div class="flow-step"><strong>Kayak 与复盘</strong><span>建议、缺失证据、验证</span></div></div><p>明确区分工作簿观察、你的建议、待验证条件。对于尚未测试的机会，不编写历史回报。</p></section>${note('q4')}`;
}
function lesson(id){const l=lessons.find(x=>x.id===id);const content=state.tab==='task'?task(id):state.tab==='reference'?extra.initial(id)+(id==='q4'?extra.chain():'')+note(id):!state.data?empty():({q1,q2,q3,q4}[id])();return head(`DECISION ${l.n} / ${l.tag}`,l.title,l.desc,`<span class="pill subtle">${l.time} 分钟 · 25 分</span>`)+`<div class="tabs" role="tablist" aria-label="题目视图">${[['task','问题与完整解答'],['analysis','交互分析'],['reference','练习与作答']].map(([k,v])=>`<button role="tab" id="tab-${k}" aria-controls="lesson-content" aria-selected="${state.tab===k}" tabindex="${state.tab===k?'0':'-1'}" class="${state.tab===k?'selected':''}" data-action="tab" data-tab="${k}">${v}</button>`).join('')}</div>${source()}<div id="lesson-content" role="tabpanel" aria-labelledby="tab-${state.tab}">${content}</div><div class="lesson-navigation"><a class="button" href="#${id==='q1'?'overview':'q'+(Number(l.n)-1)}">← ${id==='q1'?'案例故事':'上一道题'}</a><a class="button primary" href="#${id==='q4'?'notes':'q'+(Number(l.n)+1)}">${id==='q4'?'整理我的记录':'下一道题'} →</a></div>`}

function dictionary(){return `<div class="table-scroll"><table><caption>指标口径与公式</caption><thead><tr><th>指标</th><th>计算方式</th><th>单位</th><th>注意事项</th></tr></thead><tbody>${metricDefinitions.map(m=>`<tr><th>${m[0]}<small>${m[1]}</small></th><td>${m[2]}</td><td>${m[3]}</td><td class="prose-cell">${m[4]}</td></tr>`).join('')}</tbody></table></div>`}
function data(){const d=state.data;return head('SOURCE WORKBOOK / 数据查看','从一个单元格，回到经营判断。','可查看原始工作表、筛选明细、定位源行；原数据与分析汇总分开显示。')+source()+dataExplorer(state)+`<section class="panel"><h2>导入与原件</h2><p>本地完整镜像会自动读取。你也可以导入自己取得的 XLS / XLSX / CSV，图表和解答数值将随文件重算；文件不上传。</p><label class="file-button button primary" for="case-file">${d?'更换案例文件':'选择 Excel / CSV 文件'} ↗</label><input id="case-file" type="file" accept=".xls,.xlsx,.csv" class="file-input"><div id="import-message" role="status"></div>${d?`<details class="hint"><summary>当前数据检查与指纹</summary><p>${num(d.rows.length)} 条主表明细 · ${num(d.audit.zeroBookings)} 条零预订 · ${num(d.audit.bookingsAboveClicks)} 条预订高于点击 · ${num(d.audit.blankRows)} 行空白（原表查看器保留）。</p><p>${esc(d.meta.authority)} · ${esc(d.meta.period)}</p><code class="file-hash">${esc(d.meta.sha256)}</code></details>`:''}</section><details class="resource-fold"><summary>数据集介绍、来源与下载</summary>${datasetIntro(localAvailable,d)}</details><details class="resource-fold"><summary>原始字段与指标字典</summary>${fieldDictionary()}<section class="panel">${dictionary()}</section></details>`}

function brief(){return head('CASE BRIEF / AIR FRANCE','先理解真实的决策，再打开分析。','业务背景来自官方案例摘要，四题分别对应有来源的讨论主题。')+caseStory()+sourceMapping()+`<section class="panel text-block"><h2>两小时怎么完成</h2><p>先用 15 分钟讲清业务困境、10 分钟查看原始数据，再依次完成 20 分钟 KPI、25 分钟渠道策略、25 分钟活动与关键词、20 分钟未来 SEM 与 Kayak，最后用 5 分钟复盘。无需机器学习。</p><p>每题的问题、答案与可视化推导同时开放；可选的练习区保留独立初判、三项证据和逐题引用。具体步骤、时间、评分与参考思路为本课安排，不能声称是 Kellogg 官方答案。</p><a class="button" href="/reference/air-france/downloads/course-guide.md" download>下载完整上机题目 ↓</a> <a class="button" href="/reference/air-france/downloads/teaching-guide.md" download>下载讲师指南 ↓</a></section><section class="panel text-block"><h2>材料与范围</h2><p>工作簿已下载公开镜像，保留来源与版权说明；尚未与官方文件逐字节核验。<a href="${sources.purchase}" target="_blank" rel="noopener">KEL319 案例正文</a> 与 <a href="${sources.data}" target="_blank" rel="noopener">KEL321 数据附件</a> 是分别提供的教学材料，本网站没有重发受版权保护的完整案例正文。</p><p>现有表格覆盖历史搜索广告经营评价、渠道、活动与关键词，以及 Kayak 汇总。没有完整用户旅程、竞价日志、退款或履约成本，不能凭空补成企业完整财务数据。</p><a class="button primary" href="#q1">开始第一题 →</a></section>`}

function notes(){return head('MY WORKBOOK','把四个判断，连成一份方案。','作答保存在此浏览器，导出 Markdown 可交给讲师或带到下一次讨论。','<button class="button primary" data-action="export-notes">导出全部作答 ↓</button>')+`<div class="notes-grid">${lessons.map(l=>`<section class="panel"><div class="section-head no-margin"><h2>${l.n} ${l.title}</h2><span class="pill ${extra.submitted(l.id)?'ready':'subtle'}">${extra.submitted(l.id)?'证据已提交':'待完成'}</span></div><p class="small">${l.output}</p><div class="note-preview">${esc(state.notes[l.id]?.text||'还没有分析记录。进入题目后写下你的判断。')}</div>${state.notes[l.id]?.scenario?'<p class="small">含已保存预算情景</p>':''}<a class="button compact" href="#${l.id}">继续本题 →</a></section>`).join('')}</div><div class="notice info"><p>提交表示已填写结论和证据，不代表讲师评阅通过。清理浏览器数据会移除记录，请及时导出。</p></div>`}
return {overview:()=>overview(localAvailable,state.data),brief,data,notes,lesson,source,empty};
}
